```css
/* ================= DentaVoice — Geist-system tokens ================= */
:root {
  --ink: #171717;
  --body: #4d4d4d;
  --mute: #8f8f8f;
  --faint: #a1a1a1;
  --hairline: #ebebeb;
  --hairline-soft: #f2f2f2;
  --canvas: #fafafa;
  --elevated: #ffffff;
  --blue: #0070f3;
  --blue-deep: #0761d1;
  --blue-soft: #d3e5ff;
  --red: #ee0000;
  --red-soft: #ffe5e5;
  --amber: #f5a623;
  --amber-soft: #ffefcf;
  --amber-deep: #ab570a;
  --tooth-line: #c3c9d6;

  --sans: "Geist", Inter, Arial, sans-serif;

  --r-sm: 6px;
  --r-md: 12px;
  --r-lg: 16px;

  --shadow-1: 0px 1px 1px rgba(0,0,0,0.04);
  --shadow-2: 0px 2px 2px rgba(0,0,0,0.04), 0px 8px 16px -4px rgba(0,0,0,0.08);
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html, body { height: 100%; }

body {
  font-family: var(--sans);
  font-size: 14px;
  line-height: 20px;
  color: var(--ink);
  background: var(--canvas);
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.mono { font-family: var(--sans); }

/* Scroll containers scroll without visible scrollbars */
.feed, .chart-pane, .note-body {
  scrollbar-width: none;
}
.feed::-webkit-scrollbar,
.chart-pane::-webkit-scrollbar,
.note-body::-webkit-scrollbar {
  display: none;
}

.eyebrow {
  font-family: var(--sans);
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.04em;
  color: var(--mute);
}

/* ================= Top bar ================= */
.topbar {
  height: 56px;
  flex: none;
  background: var(--canvas);
  border-bottom: 1px solid var(--hairline);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 24px;
  gap: 16px;
}

.topbar-left { display: flex; align-items: center; gap: 16px; min-width: 0; }

.wordmark { display: flex; align-items: center; gap: 8px; }
.logo-mark {
  width: 26px; height: 26px;
  border-radius: 7px;
  background: var(--ink);
  color: #fff;
  display: grid;
  place-items: center;
}
.wordmark-text {
  font-size: 17px;
  font-weight: 600;
  letter-spacing: -0.4px;
}

.topbar-divider { width: 1px; height: 24px; background: var(--hairline); }

.back-btn {
  width: 30px; height: 30px;
  flex: none;
  border-radius: var(--r-sm);
  border: 1px solid var(--hairline);
  background: var(--elevated);
  color: var(--body);
  cursor: pointer;
  display: grid;
  place-items: center;
  transition: border-color 0.12s ease, background 0.12s ease;
}
.back-btn:hover { border-color: #d4d4d4; background: var(--canvas); }

.patient { display: flex; align-items: center; gap: 10px; min-width: 0; }
.patient-avatar {
  width: 32px; height: 32px;
  flex: none;
  border-radius: 9999px;
  border: 1px solid var(--hairline);
  object-fit: cover;
  display: block;
}
.patient-name { font-size: 14px; font-weight: 500; letter-spacing: -0.28px; }
.patient-sub { font-size: 12px; line-height: 16px; color: var(--mute); }

.topbar-right { display: flex; align-items: center; gap: 8px; }
.exam-date { font-size: 12px; color: var(--mute); margin-right: 8px; }

/* Buttons — app chrome: 6px squares per Geist */
.btn {
  font-family: var(--sans);
  font-size: 14px;
  font-weight: 500;
  line-height: 20px;
  padding: 6px 12px;
  border-radius: var(--r-sm);
  border: 1px solid transparent;
  cursor: pointer;
  transition: background 0.12s ease, border-color 0.12s ease, color 0.12s ease;
}
.btn-dark { background: var(--ink); color: #fff; }
.btn-dark:hover { background: #383838; }
.btn-ghost {
  background: var(--elevated);
  color: var(--ink);
  border-color: var(--hairline);
}
.btn-ghost:hover { border-color: #d4d4d4; background: var(--canvas); }

/* ================= App layout ================= */
.app {
  flex: 1;
  display: flex;
  min-height: 0;
}

.chart-pane {
  flex: 1;
  min-width: 0;
  overflow-y: auto;
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.card {
  background: var(--elevated);
  border: 1px solid var(--hairline);
  border-radius: var(--r-md);
  box-shadow: var(--shadow-1);
}

.card-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: 20px 24px 12px;
}

.card-title {
  font-size: 20px;
  font-weight: 600;
  line-height: 28px;
  letter-spacing: -0.4px;
  margin-top: 2px;
}
.card-title-sm {
  font-size: 16px;
  font-weight: 600;
  line-height: 24px;
  letter-spacing: -0.32px;
  margin-top: 2px;
}

/* ================= Legend ================= */
.legend {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 14px;
  padding-top: 6px;
  justify-content: flex-end;
}
.legend-item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  line-height: 16px;
  color: var(--body);
  white-space: nowrap;
}
.swatch {
  width: 12px; height: 12px;
  border-radius: 3px;
  display: inline-grid;
  place-items: center;
  font-size: 9px;
  line-height: 1;
}
.swatch-existing { background: var(--blue); }
.swatch-planned { background: var(--red); opacity: 0.92; }
.swatch-watch { background: var(--amber); }
.swatch-missing { background: transparent; border: 1px solid var(--faint); color: var(--faint); border-radius: 3px; }
.swatch-crown { background: #fff; border: 2.5px solid var(--blue); border-radius: 4px; }

/* ================= Odontogram ================= */
.chart-card { padding-bottom: 20px; }

.arch-label {
  font-size: 10px;
  letter-spacing: 0.05em;
  color: var(--faint);
  padding: 10px 24px 6px;
}
.arch-label-bottom { padding-top: 8px; padding-bottom: 0; }

.tooth-grid {
  display: grid;
  grid-template-columns: repeat(8, minmax(0, 1fr)) 18px repeat(8, minmax(0, 1fr));
  gap: 6px;
  padding: 0 24px;
  position: relative;
}
.midline {
  justify-self: center;
  align-self: stretch;
  width: 1px;
  background: var(--hairline);
}

.arch-divider {
  height: 1px;
  background: var(--hairline);
  margin: 16px 24px;
}

.tooth {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  cursor: pointer;
  border-radius: 8px;
  padding: 4px 2px;
  transition: background 0.12s ease;
  border: none;
  background: transparent;
  font-family: inherit;
}
.tooth:hover { background: var(--hairline-soft); }
.tooth.selected { background: var(--blue-soft); }

.tooth-num {
  font-family: var(--sans);
  font-size: 11.5px;
  font-weight: 500;
  color: var(--mute);
}
.tooth.selected .tooth-num { color: var(--blue-deep); }

.tooth svg { width: 100%; max-width: 52px; height: auto; display: block; }

.tooth.flash svg { animation: toothflash 0.9s ease; }
@keyframes toothflash {
  0% { transform: scale(1); }
  25% { transform: scale(1.14); }
  100% { transform: scale(1); }
}

.watch-dot {
  width: 5px; height: 5px;
  border-radius: 9999px;
  background: var(--amber);
  margin-top: -1px;
}
.watch-dot-placeholder { width: 5px; height: 5px; margin-top: -1px; }

/* ================= Findings table ================= */
.findings-card { flex: none; }

.findings-head-left { display: flex; flex-direction: column; }
.findings-head-right { display: flex; align-items: center; gap: 10px; padding-top: 4px; }

.stat-chips { display: flex; gap: 6px; }

.tooth-filter[hidden] { display: none; }
.tooth-filter {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  font-weight: 500;
  color: var(--blue-deep);
  background: #f0f6ff;
  border: 1px solid var(--blue-soft);
  border-radius: 9999px;
  padding: 3px 6px 3px 10px;
}
.tooth-filter button {
  border: none;
  background: transparent;
  color: var(--blue-deep);
  cursor: pointer;
  font-size: 10px;
  padding: 2px 4px;
  border-radius: 9999px;
}
.tooth-filter button:hover { background: var(--blue-soft); }

.table-wrap { padding: 4px 8px 12px; }

.findings-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 14px;
}
.findings-table th {
  font-family: var(--sans);
  font-size: 11px;
