/* ================================================================
   DentaVoice — voice-driven dental base charting (interactive prototype)
   ================================================================ */

/* ---------------- Tooth reference data ---------------- */

const UPPER = [18,17,16,15,14,13,12,11, 21,22,23,24,25,26,27,28];
const LOWER = [48,47,46,45,44,43,42,41, 31,32,33,34,35,36,37,38];
const ALL_TEETH = [...UPPER, ...LOWER];

const POSITION_NAMES = {
  1: "central incisor", 2: "lateral incisor", 3: "canine",
  4: "first premolar", 5: "second premolar",
  6: "first molar", 7: "second molar", 8: "third molar",
};
const QUAD_NAMES = { 1: "Upper right", 2: "Upper left", 3: "Lower left", 4: "Lower right" };

function toothName(fdi) {
  const q = Math.floor(fdi / 10), p = fdi % 10;
  return `${QUAD_NAMES[q]} ${POSITION_NAMES[p]}`;
}
function isUpper(fdi) { const q = Math.floor(fdi / 10); return q === 1 || q === 2; }
function isAnterior(fdi) { return fdi % 10 <= 3; }

/* FDI <-> Universal (1–32) */
const FDI_TO_UNI = {};
const UNI_TO_FDI = {};
[...UPPER, ...[38,37,36,35,34,33,32,31, 41,42,43,44,45,46,47,48]].forEach((fdi, i) => {
  FDI_TO_UNI[fdi] = i + 1;
  UNI_TO_FDI[i + 1] = fdi;
});

function toothDisplay(fdi) {
  return state.notation === "UNIVERSAL" ? String(FDI_TO_UNI[fdi]) : String(fdi);
}

/* Surface display: canonical keys M D B L O */
function surfaceLetter(key, fdi) {
  if (key === "L" && isUpper(fdi)) return "P";       // palatal on uppers
  if (key === "O" && isAnterior(fdi)) return "I";    // incisal on anteriors
  return key;
}
const SURFACE_WORDS = {
  M: "mesial", D: "distal", B: "buccal", L: "lingual", O: "occlusal",
};
function surfaceWord(key, fdi) {
  if (key === "L" && isUpper(fdi)) return "palatal";
  if (key === "O" && isAnterior(fdi)) return "incisal";
  return SURFACE_WORDS[key];
}

/* ---------------- State ---------------- */

const state = {
  actions: [],        // charting actions (source of truth; teeth derived by replay)
  feed: [],           // transcript + action + error entries
  listening: false,
  notation: "FDI",
  autoChart: true,
  selectedTooth: null,
  demoRunning: false,
  counter: 0,
};

const uid = () => "a" + (++state.counter);
const now = () => new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });

/* ---------------- Parser ---------------- */

const MATERIALS = [
  ["glass ionomer", "Glass ionomer"],
  ["composite", "Composite"],
  ["amalgam", "Amalgam"],
  ["sealant", "Sealant"],
  ["gold inlay", "Gold inlay"],
  ["gold onlay", "Gold onlay"],
  ["inlay", "Inlay"],
  ["onlay", "Onlay"],
  ["veneer", "Veneer"],
  ["filling", "Filling"],
];
const CROWN_MATERIALS = [
  ["pfm", "PFM"], ["porcelain fused to metal", "PFM"], ["zirconia", "Zirconia"],
  ["emax", "e.max"], ["e.max", "e.max"], ["all ceramic", "Ceramic"],
  ["ceramic", "Ceramic"], ["porcelain", "Porcelain"], ["gold", "Gold"],
  ["stainless steel", "Stainless steel"],
];

const SURFACE_LOOKUP = {
  mesial: "M", distal: "D", buccal: "B", facial: "B", vestibular: "B",
  lingual: "L", palatal: "L", occlusal: "O", incisal: "O",
};

function parseSurfaces(clause) {
  const found = [];
  const push = (s) => { if (s && !found.includes(s)) found.push(s); };
  // full words
  for (const [word, key] of Object.entries(SURFACE_LOOKUP)) {
    if (new RegExp(`\\b${word}\\b`, "i").test(clause)) push(key);
  }
  // letter runs like "MOD", "MO", "DO", "OB" (2+ letters, all surface codes)
  const runs = clause.match(/\b[MODBLPIF]{2,5}\b/g) || [];
  for (const run of runs) {
    if (/^(DO|MOD|MO|OB|OL|OP|MB|DB|ML|DL|MI|DI|BL|MODB|MODL|MODBL)$/i.test(run.toUpperCase()) ||
        [...run.toUpperCase()].every((c) => "MODBLPIF".includes(c))) {
      for (const c of run.toUpperCase()) {
        push({ M:"M", O:"O", D:"D", B:"B", L:"L", P:"L", I:"O", F:"B" }[c]);
      }
    }
  }
  return found;
}

function parseToothNumber(clause) {
  const nums = clause.match(/\b\d{1,2}\b/g) || [];
  for (const n of nums) {
    const v = parseInt(n, 10);
    if (state.notation === "UNIVERSAL") {
      if (UNI_TO_FDI[v]) return UNI_TO_FDI[v];
    } else if (ALL_TEETH.includes(v)) {
      return v;
    }
  }
  return null;
}

/* Parse one utterance into a list of actions (or per-clause errors). */
function parseUtterance(text) {
  const results = [];
  const clauses = text.split(/,|;|\band then\b|\bthen\b|\balso\b/i).map(s => s.trim()).filter(Boolean);
  let lastTooth = null;
  let lastSurfaces = [];

  for (const clause of clauses) {
    const lower = clause.toLowerCase();

    // voice corrections
    if (/^(undo|scratch that|delete that|remove that|cancel that)/i.test(lower)) {
      results.push({ kind: "undo-last" });
      continue;
    }

    const toothInClause = parseToothNumber(clause);
    const tooth = toothInClause || lastTooth;
    if (!tooth) {
      results.push({ error: clause });
      continue;
    }
    lastTooth = tooth;

    let surfaces = parseSurfaces(clause);
    const planned = /\b(plan|planned|planning|needs?|recommend|schedule|to be|tx)\b/i.test(lower);

    let action = null;

    if (/\bmissing\b|\babsent\b|\bedentulous\b/.test(lower)) {
      action = { kind: "missing", tooth };
    } else if (/\bextract/.test(lower)) {
      action = { kind: "extraction", tooth, status: "planned" };
    } else if (/\bimplant\b/.test(lower)) {
      action = { kind: "implant", tooth, status: planned ? "planned" : "existing" };
    } else if (/\broot canal\b|\brct\b|\bendo\b/.test(lower)) {
      action = { kind: "rct", tooth, status: planned ? "planned" : "existing" };
    } else if (/\bcrown\b/.test(lower)) {
      let mat = null;
      for (const [w, label] of CROWN_MATERIALS) {
        if (lower.includes(w)) { mat = label; break; }
      }
      action = { kind: "crown", tooth, material: mat, status: planned ? "planned" : "existing" };
    } else if (/\bwatch\b|\bmonitor\b/.test(lower)) {
      action = surfaces.length
        ? { kind: "watch", tooth, surfaces }
        : { kind: "watch-tooth", tooth };
    } else if (/\bcaries\b|\bdecay\b|\bcavity\b|\bcarious\b/.test(lower)) {
      if (!surfaces.length) surfaces = ["O"];
      action = { kind: "caries", tooth, surfaces };
    } else {
      let mat = null;
      for (const [w, label] of MATERIALS) {
        if (lower.includes(w)) { mat = label; break; }
      }
      if (mat) {
        if (!surfaces.length) {
          // "plan composite" after "26 MOD caries" inherits the surfaces
          surfaces = (tooth === lastTooth && lastSurfaces.length) ? [...lastSurfaces] : ["O"];
        }
        action = { kind: "restoration", tooth, surfaces, material: mat, status: planned ? "planned" : "existing" };
      }
    }

    if (action) {
      if (action.surfaces) lastSurfaces = [...action.surfaces];
      results.push(action);
    } else if (toothInClause && surfaces.length) {
      results.push({ error: clause });
    } else {
      results.push({ error: clause });
    }
  }
  return results;
}

/* ---------------- Derived chart model (replay) ---------------- */

function deriveTeeth() {
  const teeth = {};
  const t = (fdi) => (teeth[fdi] ||= { surfaces: {}, watch: false, missing: false,
    extraction: false, crown: null, rct: null, implant: null });

  for (const a of state.actions) {
    switch (a.kind) {
      case "restoration":
        for (const s of a.surfaces) t(a.tooth).surfaces[s] = { fill: a.status === "planned" ? "red" : "blue" };
        break;
      case "caries":
        for (const s of a.surfaces) t(a.tooth).surfaces[s] = { fill: "red" };
        break;
      case "watch":
        for (const s of a.surfaces) t(a.tooth).surfaces[s] = { fill: "amber" };
        break;
      case "watch-tooth": t(a.tooth).watch = true; break;
      case "missing": t(a.tooth).missing = true; break;
      case "extraction": t(a.tooth).extraction = true; break;
      case "crown": t(a.tooth).crown = { status: a.status }; break;
      case "rct": t(a.tooth).rct = { status: a.status }; break;
      case "implant": t(a.tooth).implant = { status: a.status }; break;
    }
  }
  return teeth;
}

/* ---------------- Odontogram rendering ---------------- */

const FILL_COLORS = { blue: "#0070f3", red: "#f0453d", amber: "#f5a623" };

/* Which surface each glyph region maps to, per tooth position on screen. */
function regionSurfaces(fdi) {
  const q = Math.floor(fdi / 10);
  const upper = isUpper(fdi);
  const mesialRight = q === 1 || q === 4;   // left half of the screen: midline is to the right
  return {
    top:    upper ? "B" : "L",
    bottom: upper ? "L" : "B",
    left:   mesialRight ? "D" : "M",
    right:  mesialRight ? "M" : "D",
    center: "O",
  };
}

function toothSVG(fdi, data) {
  const map = regionSurfaces(fdi);
  const line = "#c3c9d6";
  const clipId = `clip${fdi}`;

  const regionShapes = {
    top:    `<polygon points="2,2 62,2 43,21 21,21"/>`,
    bottom: `<polygon points="2,62 62,62 43,43 21,43"/>`,
    left:   `<polygon points="2,2 21,21 21,43 2,62"/>`,
    right:  `<polygon points="62,2 43,21 43,43 62,62"/>`,
    center: `<rect x="21" y="21" width="22" height="22" rx="2"/>`,
  };

  let fills = "";
  for (const [region, shape] of Object.entries(regionShapes)) {
    const surf = map[region];
    const entry = data && data.surfaces[surf];
    if (entry) {
      const color = FILL_COLORS[entry.fill];
      fills += shape.replace("/>", ` fill="${color}"/>`);
    }
  }

  const crown = data && data.crown;
  const crownColor = crown ? (crown.status === "planned" ? FILL_COLORS.red : FILL_COLORS.blue) : null;
  const outerStroke = crownColor || line;
  const outerWidth = crown ? 3.4 : 1.6;

  const missing = data && data.missing;
  const extraction = data && data.extraction;
  const implant = data && data.implant;

  let overlay = "";
