    const c = implant.status === "planned" ? FILL_COLORS.red : FILL_COLORS.blue;
    overlay += `<g stroke="${c}" stroke-width="2" stroke-linecap="round">
      <line x1="26" y1="26" x2="38" y2="26"/><line x1="27" y1="32" x2="37" y2="32"/><line x1="28" y1="38" x2="36" y2="38"/></g>`;
  }

  return `<svg viewBox="0 0 64 64" ${missing ? 'style="opacity:0.32"' : ""}>
    <defs><clipPath id="${clipId}"><rect x="2" y="2" width="60" height="60" rx="14"/></clipPath></defs>
    <g clip-path="url(#${clipId})">${fills}</g>
    <g fill="none" stroke="${line}" stroke-width="1.6">
      <line x1="7" y1="7" x2="21" y2="21"/><line x1="57" y1="7" x2="43" y2="21"/>
      <line x1="7" y1="57" x2="21" y2="43"/><line x1="57" y1="57" x2="43" y2="43"/>
      <rect x="21" y="21" width="22" height="22" rx="3"/>
    </g>
    <rect x="2" y="2" width="60" height="60" rx="14" fill="none" stroke="${outerStroke}" stroke-width="${outerWidth}"/>
    ${overlay}
  </svg>`;
}

function renderArch(el, teethList, teethData, numbersOnTop) {
  el.innerHTML = "";
  teethList.forEach((fdi, i) => {
    if (i === 8) {
      const mid = document.createElement("div");
      mid.className = "midline";
      el.appendChild(mid);
    }
    const data = teethData[fdi];
    const btn = document.createElement("button");
    btn.className = "tooth" + (state.selectedTooth === fdi ? " selected" : "");
    btn.dataset.tooth = fdi;
    btn.title = `${toothDisplay(fdi)} — ${toothName(fdi)}`;

    const num = `<span class="tooth-num">${toothDisplay(fdi)}</span>`;
    const svg = toothSVG(fdi, data);
    const watch = data && data.watch
      ? `<span class="watch-dot" title="Watch"></span>`
      : `<span class="watch-dot-placeholder"></span>`;

    btn.innerHTML = numbersOnTop ? num + svg + watch : watch + svg + num;
    btn.addEventListener("click", () => {
      state.selectedTooth = state.selectedTooth === fdi ? null : fdi;
      renderAll();
    });
    el.appendChild(btn);
  });
}

function flashTeeth(fdis) {
  for (const fdi of fdis) {
    const el = document.querySelector(`.tooth[data-tooth="${fdi}"]`);
    if (el) {
      el.classList.remove("flash");
      void el.offsetWidth;
      el.classList.add("flash");
    }
  }
}

/* ---------------- Findings table ---------------- */

function actionArea(a) {
  if (a.surfaces) return a.surfaces.map((s) => surfaceLetter(s, a.tooth)).join("");
  return "Full";
}

function actionFinding(a) {
  switch (a.kind) {
    case "restoration": return a.material;
    case "caries": return "Caries";
    case "watch": case "watch-tooth": return "Watch";
    case "missing": return "Missing";
    case "extraction": return "Extraction";
    case "crown": return a.material ? `Crown — ${a.material}` : "Crown";
    case "rct": return "Root canal";
    case "implant": return "Implant";
    default: return a.kind;
  }
}

function actionStatus(a) {
  if (a.kind === "caries") return "planned";
  if (a.kind === "watch" || a.kind === "watch-tooth") return "watch";
  if (a.kind === "missing") return "info";
  if (a.kind === "extraction") return "planned";
  return a.status || "existing";
}

const STATUS_LABELS = { existing: "Existing", planned: "Planned", watch: "Watch", info: "Noted" };

function renderFindings() {
  const body = document.getElementById("findings-body");
  const empty = document.getElementById("empty-findings");
  const filter = state.selectedTooth;

  const rows = state.actions.filter((a) => !filter || a.tooth === filter);

  body.innerHTML = "";
  empty.hidden = rows.length > 0;

  for (const a of [...rows].reverse()) {
    const status = actionStatus(a);
    const tr = document.createElement("tr");
    tr.innerHTML = `
      <td class="td-tooth">${toothDisplay(a.tooth)}</td>
      <td class="td-area">${actionArea(a)}</td>
      <td>${actionFinding(a)}<span style="color:var(--mute)"> · ${toothName(a.tooth)}</span></td>
      <td><span class="badge badge-${status}">${STATUS_LABELS[status]}</span></td>
      <td class="td-time">${a.time}</td>
      <td><button class="undo-btn" data-id="${a.id}">Remove</button></td>`;
    tr.querySelector(".undo-btn").addEventListener("click", (e) => {
      e.stopPropagation();
      undoAction(a.id, true);
    });
    body.appendChild(tr);
  }

  // header counts
  const total = state.actions.length;
  document.getElementById("findings-count").textContent =
    `${total} ${total === 1 ? "entry" : "entries"}`;

  const existing = state.actions.filter((a) => actionStatus(a) === "existing").length;
  const planned = state.actions.filter((a) => actionStatus(a) === "planned").length;
  const missing = state.actions.filter((a) => a.kind === "missing").length;
  const chips = document.getElementById("stat-chips");
  chips.innerHTML = `
    <span class="badge badge-existing">${existing} existing</span>
    <span class="badge badge-planned">${planned} planned</span>
    <span class="badge badge-info">${missing} missing</span>`;

  const fEl = document.getElementById("tooth-filter");
  fEl.hidden = !filter;
  if (filter) {
    document.getElementById("tooth-filter-label").textContent =
      `Tooth ${toothDisplay(filter)} — ${toothName(filter)}`;
  }
}

/* ---------------- Feed ---------------- */

function actionDescription(a) {
  const t = toothDisplay(a.tooth);
  const surf = a.surfaces ? a.surfaces.map((s) => surfaceWord(s, a.tooth)).join(" + ") : null;
  switch (a.kind) {
    case "restoration": return `${a.material} — tooth ${t}, ${surf}`;
    case "caries": return `Caries — tooth ${t}, ${surf}`;
    case "watch": return `Watch — tooth ${t}, ${surf}`;
    case "watch-tooth": return `Watch — tooth ${t}`;
    case "missing": return `Tooth ${t} charted missing`;
    case "extraction": return `Extraction — tooth ${t}`;
    case "crown": return `${a.material ? a.material + " crown" : "Crown"} — tooth ${t}`;
    case "rct": return `Root canal — tooth ${t}`;
    case "implant": return `Implant — tooth ${t}`;
    default: return a.kind;
  }
}

function renderFeed() {
  const feed = document.getElementById("feed");
  feed.innerHTML = "";

  if (!state.feed.length) {
    feed.innerHTML = `<div class="feed-empty">Transcript and charted actions will appear here as you speak.</div>`;
    return;
  }

  const firstTranscript = state.feed.find((e) => e.type === "transcript");
  if (firstTranscript) {
    const header = document.createElement("div");
    header.className = "feed-speaker";
    header.textContent = firstTranscript.speaker;
    feed.appendChild(header);
  }

  for (const entry of state.feed) {
    if (entry.type === "transcript") {
      const div = document.createElement("div");
      div.className = "utterance";
      div.innerHTML = `
        <span class="utt-text">${entry.text}</span>
        <span class="utt-time">${entry.time}</span>`;
      feed.appendChild(div);
    } else if (entry.type === "action") {
      const a = state.actions.find((x) => x.id === entry.actionId);
      const badge = a
        ? `<span class="badge badge-${entry.status || "existing"}">${STATUS_LABELS[entry.status] || "Charted"}</span>`
        : `<span class="badge badge-info">Removed</span>`;
      const div = document.createElement("div");
      div.className = "action-card";
      div.innerHTML = `
        <div class="action-body">
          <div class="action-top">${badge}</div>
          <div class="action-desc" ${a ? "" : 'style="color:var(--mute);text-decoration:line-through"'}>${entry.desc}</div>
        </div>
        <button class="action-undo" data-id="${entry.actionId}" ${a ? "" : "disabled"}>Undo</button>`;
      if (a) {
        div.querySelector(".action-undo").addEventListener("click", () => undoAction(entry.actionId, false));
      }
      feed.appendChild(div);
    } else if (entry.type === "error") {
      const div = document.createElement("div");
      div.className = "action-card";
      div.innerHTML = `
        <div class="action-body">
          <div class="action-top"><span class="badge badge-watch">Needs review</span></div>
          <div class="action-desc">Couldn't chart “${entry.text}” — try tooth + surface + finding.</div>
        </div>`;
      feed.appendChild(div);
    }
  }
  feed.scrollTop = feed.scrollHeight;
}

/* ---------------- Actions ---------------- */

function applyParsed(parsed, { flash = true } = {}) {
  const touched = [];
  for (const p of parsed) {
    if (p.error) {
      state.feed.push({ type: "error", text: p.error });
      continue;
    }
    if (p.kind === "undo-last") {
      const last = state.actions[state.actions.length - 1];
      if (last) undoAction(last.id, false, { silentRender: true });
      continue;
    }
    const action = { ...p, id: uid(), time: now() };
    state.actions.push(action);
    state.feed.push({ type: "action", actionId: action.id,
      desc: actionDescription(action), status: actionStatus(action) });
    touched.push(action.tooth);
  }
  renderAll();
  if (flash && touched.length) flashTeeth(touched);
}

function undoAction(id, fromTable, { silentRender = false } = {}) {
  const idx = state.actions.findIndex((a) => a.id === id);
  if (idx === -1) return;
  state.actions.splice(idx, 1);
  if (fromTable) {
    // drop the matching feed card entirely
    const fIdx = state.feed.findIndex((e) => e.type === "action" && e.actionId === id);
    if (fIdx !== -1) state.feed.splice(fIdx, 1);
  }
  if (!silentRender) renderAll();
}

function speak(text, { speaker = "Dr. Erika", flash = true } = {}) {
  state.feed.push({ type: "transcript", speaker, text, time: now() });
  const parsed = parseUtterance(text);
  if (state.autoChart) {
    applyParsed(parsed, { flash });
  } else {
    renderAll();
  }
}

/* ---------------- Rendering root ---------------- */

function renderAll() {
  const teeth = deriveTeeth();
  renderArch(document.getElementById("upper-arch"), UPPER, teeth, true);
  renderArch(document.getElementById("lower-arch"), LOWER, teeth, false);
  renderFindings();
  renderFeed();
}

/* ---------------- Clinical note export ---------------- */

function buildNote() {
  const lines = [];
  const date = new Date().toLocaleDateString([], { year: "numeric", month: "long", day: "numeric" });
  lines.push(`Comprehensive exam — Base charting`);
  lines.push(`Patient: Sarah Mitchell (Chart #4821)`);
  lines.push(`Provider: Dr. Erika · Charted by voice with DentaVoice`);
  lines.push(`Date: ${date}`);
  lines.push("");

  const group = (label, filterFn) => {
    const items = state.actions.filter(filterFn);
    if (!items.length) return;
    lines.push(label);
    for (const a of items) {
      const surf = a.surfaces ? ` (${a.surfaces.map((s) => surfaceWord(s, a.tooth)).join(", ")})` : "";
      lines.push(`  · Tooth ${toothDisplay(a.tooth)} — ${actionFinding(a)}${surf}`);
    }
    lines.push("");
  };

  group("Existing restorations", (a) => actionStatus(a) === "existing");
  group("Findings & treatment plan", (a) => actionStatus(a) === "planned");
  group("Watch list", (a) => actionStatus(a) === "watch");
  group("Missing teeth", (a) => a.kind === "missing");

  if (state.actions.length === 0) lines.push("No findings charted.");
  return lines.join("\n");
}

/* ---------------- Demo exam ---------------- */

const SEED_UTTERANCE = "18 buccal composite, 17 palatal composite, 17 buccal amalgam";

const DEMO_SCRIPT = [
  "16 occlusal amalgam",
  "25 is missing",
  "26 MOD caries, plan composite",
  "36 existing PFM crown",
  "watch 44 buccal",
  "38 needs extraction",
  "46 occlusal composite",
];

function resetExam() {
  state.actions = [];
  state.feed = [];
  state.selectedTooth = null;
  speak(SEED_UTTERANCE, { flash: false });
}

function runDemo() {
  if (state.demoRunning) return;
  state.demoRunning = true;
  resetExam();
  setListening(true);
  const btn = document.getElementById("btn-demo");
  btn.disabled = true;
  btn.textContent = "Dictating…";

  let i = 0;
  const step = () => {
    if (i >= DEMO_SCRIPT.length) {
      state.demoRunning = false;
      btn.disabled = false;
      btn.textContent = "▶ Play demo exam";
      setListening(false);
      return;
    }
    speak(DEMO_SCRIPT[i]);
    i++;
    setTimeout(step, 1900);
  };
  setTimeout(step, 600);
}

/* ---------------- Mic / settings wiring ---------------- */

function setListening(on) {
  state.listening = on;
  const micBtn = document.getElementById("mic-btn");
  const status = document.getElementById("listen-status");
  micBtn.classList.toggle("live", on);
  status.classList.toggle("live", on);
  document.getElementById("listen-status-text").textContent = on ? "Listening" : "Idle";
  document.getElementById("mic-caption").textContent = on
    ? "Listening — speak naturally"
    : "Tap to start dictating";
}

function init() {
  document.getElementById("exam-date").textContent =
    new Date().toLocaleDateString([], { month: "short", day: "numeric", year: "numeric" });

  document.getElementById("btn-back").addEventListener("click", () => history.back());
  document.getElementById("mic-btn").addEventListener("click", () => setListening(!state.listening));
  document.getElementById("btn-demo").addEventListener("click", runDemo);

  // simulate-dictation input
  const input = document.getElementById("dictate-input");
  const send = () => {
    const text = input.value.trim();
    if (!text) return;
    input.value = "";
    speak(text);
  };
  document.getElementById("dictate-send").addEventListener("click", send);
  input.addEventListener("keydown", (e) => { if (e.key === "Enter") send(); });

  // settings
  document.getElementById("set-notation").addEventListener("click", (e) => {
    const btn = e.target.closest("button");
    if (!btn) return;
    state.notation = btn.dataset.notation;
    document.querySelectorAll("#set-notation button").forEach((b) =>
      b.classList.toggle("seg-on", b === btn));
    renderAll();
  });

  const wireToggle = (id, cb) => {
    const el = document.getElementById(id);
    el.addEventListener("click", () => {
      const on = !el.classList.contains("toggle-on");
      el.classList.toggle("toggle-on", on);
      el.setAttribute("aria-checked", String(on));
      if (cb) cb(on);
    });
  };
  wireToggle("set-autochart", (on) => { state.autoChart = on; });
  wireToggle("set-voiceconfirm");

  document.getElementById("feed-clear").addEventListener("click", () => {
    state.feed = [];
    renderFeed();
  });

  document.getElementById("tooth-filter-clear").addEventListener("click", () => {
    state.selectedTooth = null;
    renderAll();
  });

  // export note modal
  const modal = document.getElementById("modal");
  document.getElementById("btn-export").addEventListener("click", () => {
    document.getElementById("note-body").textContent = buildNote();
    document.getElementById("copy-hint").textContent = "";
    modal.hidden = false;
  });
  const closeModal = () => { modal.hidden = true; };
  document.getElementById("modal-close").addEventListener("click", closeModal);
  document.getElementById("modal-done").addEventListener("click", closeModal);
  modal.addEventListener("click", (e) => { if (e.target === modal) closeModal(); });
  document.getElementById("btn-copy").addEventListener("click", async () => {
    try {
      await navigator.clipboard.writeText(document.getElementById("note-body").textContent);
      document.getElementById("copy-hint").textContent = "Copied ✓";
    } catch {
      document.getElementById("copy-hint").textContent = "Select the text to copy";
    }
  });

  document.getElementById("btn-end").addEventListener("click", () => {
    document.getElementById("note-body").textContent = buildNote();
    document.getElementById("copy-hint").textContent = "";
    modal.hidden = false;
  });

  // Open mid-exam: the seeded transcript plus the full demo exam already
  // charted, mic live — the first frame reads complete and active.
  // "Play demo exam" resets to the empty seeded exam and dictates it back in.
  resetExam();
  for (const line of DEMO_SCRIPT) speak(line, { flash: false });
  setListening(true);

  renderAll();

  if (new URLSearchParams(location.search).has("demo")) runDemo();
}

init();
```

